import pandas as pd
import numpy as np

# Load the data
crime_data = pd.read_csv('getisord_2022_crime.csv')
adjacency_data = pd.read_csv('borough_adjacency.csv')

# Handle missing values by imputing the missing value in the Crime_value column using mean imputation
crime_data['Crime_value'] = crime_data['Crime_value'].fillna(crime_data['Crime_value'].mean())

# Calculate the combined local area for each borough by summing the Crime_value for the borough and its neighbors
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])
    if row['neighbor'] not in neighborhoods:
        neighborhoods[row['neighbor']] = []
    neighborhoods[row['neighbor']].append(row['borough'])

combined_local_areas = {}
for borough in crime_data['borough']:
    combined_local_area = crime_data.loc[crime_data['borough'] == borough, 'Crime_value'].sum() + sum([crime_data.loc[crime_data['borough'] == neighbor, 'Crime_value'].sum() for neighbor in neighborhoods[borough]])
    combined_local_areas[borough] = combined_local_area

# Calculate the citywide average of the combined local areas
citywide_average = np.mean(list(combined_local_areas.values()))

# Calculate the z-score for each borough using the formula: z = (combined local area - citywide average) / (standard deviation of combined local areas)
z_scores = {}
for borough in combined_local_areas:
    z_score = (combined_local_areas[borough] - citywide_average) / np.std(list(combined_local_areas.values()))
    z_scores[borough] = z_score

# Identify hot and cold spots using the z-score and the standard critical values
hot_spots = {borough: z_score for borough, z_score in z_scores.items() if abs(z_score) > 1.96}
cold_spots = {borough: z_score for borough, z_score in z_scores.items() if abs(z_score) > 1.96 and borough not in hot_spots}

# Print the results
data_points_used = len(crime_data['borough'].unique())
print(f"data_points_used = {data_points_used}")

results = []
for borough, z_score in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={z_score}, gi_value={z_score})")
for borough, z_score in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={z_score}, gi_value={z_score})")

if results:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
